import { logger } from "@formbricks/logger";
import type { TAuthenticationApiKey } from "@formbricks/types/auth";
import { AuthorizationError, ResourceNotFoundError } from "@formbricks/types/errors";
import { type TAuthorizationActor, assertCan, can } from "@/lib/authorization";
import { getWorkspaceAuthorizationAction } from "@/lib/authorization/permission-action";
import type { TTeamPermission } from "@/modules/ee/teams/workspace-teams/types/team";
import { problemForbidden, problemUnauthorized } from "./response";
import type { TV3Authentication } from "./types";
import { type V3WorkspaceContext, resolveV3WorkspaceContext } from "./workspace-context";

export const getV3AuthorizationActor = (authentication: TV3Authentication): TAuthorizationActor | null => {
  if (authentication && "user" in authentication && authentication.user?.id) {
    return { type: "user", id: authentication.user.id };
  }

  if (authentication && "apiKeyId" in authentication && authentication.apiKeyId) {
    return { type: "apiKey", id: authentication.apiKeyId };
  }

  return null;
};

/** The signed-in user behind a session request, or `null` for an API key: who a write records as creator. */
export const getV3SessionUserId = (authentication: TV3Authentication): string | null =>
  authentication && "user" in authentication && authentication.user?.id ? authentication.user.id : null;

/**
 * Require session and workspace access. workspaceId is resolved via the V3 workspace-context layer.
 * Returns a Response (401 or 403) on failure, or the resolved workspace context on success so callers
 * use internal IDs (workspaceId, organizationId) without resolving again.
 * We use 403 (not 404) when the workspace is not found to avoid leaking resource existence.
 */
export async function requireSessionWorkspaceAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  minPermission: TTeamPermission,
  requestId: string,
  instance?: string
): Promise<Response | V3WorkspaceContext> {
  // --- Session checks ---
  if (!authentication) {
    return problemUnauthorized(requestId, "Not authenticated", instance);
  }
  if (!("user" in authentication) || !authentication.user?.id) {
    return problemUnauthorized(requestId, "Session required", instance);
  }

  const userId = authentication.user.id;
  const log = logger.withContext({ requestId, workspaceId });

  try {
    // Resolve workspaceId → workspaceId, organizationId (single place to change when Workspace exists).
    const context = await resolveV3WorkspaceContext(workspaceId);

    await assertCan({ type: "user", id: userId }, getWorkspaceAuthorizationAction(minPermission), {
      type: "workspace",
      id: context.workspaceId,
    });

    return context;
  } catch (err) {
    if (err instanceof ResourceNotFoundError || err instanceof AuthorizationError) {
      const message = err instanceof ResourceNotFoundError ? "Workspace not found" : "Forbidden";
      log.warn({ statusCode: 403, errorCode: err.name }, message);
      return problemForbidden(requestId, "You are not authorized to access this resource", instance);
    }
    throw err;
  }
}

/** Session or API key: authorize `workspaceId` against the resolved V3 workspace context. */
export async function requireV3WorkspaceAccess(
  authentication: TV3Authentication,
  workspaceId: string,
  minPermission: TTeamPermission,
  requestId: string,
  instance?: string

import { logger } from "@formbricks/logger";
import { TAuthenticationApiKey } from "@formbricks/types/auth";
import { parseApiKeyV2 } from "@/lib/crypto";
import { getApiKeyWithPermissions } from "@/modules/organization/settings/api-keys/lib/api-key";

type THeadersLike = Pick<Headers, "get">;

const BEARER_PREFIX = "bearer ";

export const getBearerTokenFromHeaders = (headers: THeadersLike): string | null => {
  const authorizationHeader = headers.get("authorization")?.trim();
  if (!authorizationHeader) {
    return null;
  }

  const lowerCasedAuthorizationHeader = authorizationHeader.toLowerCase();
  if (!lowerCasedAuthorizationHeader.startsWith(BEARER_PREFIX)) {
    return null;
  }

  const token = authorizationHeader.slice(BEARER_PREFIX.length).trim();
  return token.length > 0 ? token : null;
};
export const getApiKeyFromHeaders = (headers: THeadersLike): string | null => {
  const apiKeyHeader = headers.get("x-api-key")?.trim();
  if (apiKeyHeader) {
    return apiKeyHeader;
  }

  const bearerToken = getBearerTokenFromHeaders(headers);
  if (!bearerToken || !parseApiKeyV2(bearerToken)) {
    return null;
  }

  return bearerToken;
};

export type AuthenticateApiKeyOptions = {
  allowOrganizationOnlyApiKey?: boolean;
};

export const authenticateApiKeyFromHeaders = async (
  headers: THeadersLike,
  options: AuthenticateApiKeyOptions = {}
): Promise<TAuthenticationApiKey | null> => {
  const apiKey = getApiKeyFromHeaders(headers);
  if (!apiKey) {
    return null;
  }

  const apiKeyData = await getApiKeyWithPermissions(apiKey);
  if (!apiKeyData) {
    return null;
  }

  // ENG-1749 defense-in-depth: only honor workspace permissions whose workspace belongs to the
  // key's own organization. API keys are org-scoped, so a permission on a foreign workspace is
  // always illegitimate (it can only exist from a pre-fix bug/exploit). Filtering here — the single
  // point where the permission list is built — protects every consumer, including the read/list
  // routes that authorize off this list directly rather than through resolveBodyIdsV2.

export type TV3InvalidParam = {
  name: string;
  reason: string;
  /** What kind of problem, from v3's `InvalidParam.code`, when the operation sets one. */
  code?: string;
  /** The thing the problem is about, e.g. the import limit a file is past. */
  identifier?: string;
};

type TV3ProblemBody = {
  status?: number;
  detail?: string;
  code?: string;
  requestId?: string;
  invalid_params?: TV3InvalidParam[];
  details?: unknown;
};

export class V3ApiError extends Error {
  status: number;
  code?: string;
  requestId?: string;
  invalid_params?: TV3InvalidParam[];
  /** The problem's `details`, unparsed: their shape depends on `code`, so the caller reads them. */
  details?: unknown;
  /** Seconds to wait before asking again, from a 429's `Retry-After`. */
  retryAfter?: number;

  constructor({
    status,
    detail,
    code,
    requestId,
    invalid_params,
    details,
    retryAfter,
  }: {
    status: number;
    detail: string;
    code?: string;
    requestId?: string;
    invalid_params?: TV3InvalidParam[];
    details?: unknown;
    retryAfter?: number;
  }) {
    super(detail);
    this.name = "V3ApiError";
    this.status = status;
    this.code = code;
    this.requestId = requestId;
    this.invalid_params = invalid_params;
    this.details = details;
    this.retryAfter = retryAfter;
  }

  get detail(): string {
    return this.message;
  }
}

/** A 429 asking for a wait this short is a busy moment, worth waiting out; a longer one is a spent budget. */
const MAX_WAITED_RETRY_AFTER_SECONDS = 5;
/** How many such waits one read sits through before its error shows. */
const MAX_BUSY_RETRIES = 5;

/** A 429 that asks for a short wait, such as every in-flight chart query slot being taken. */
const isBriefBusy = (error: unknown): error is V3ApiError =>
  error instanceof V3ApiError &&
  error.status === 429 &&
  error.retryAfter !== undefined &&
  error.retryAfter <= MAX_WAITED_RETRY_AFTER_SECONDS;

/**
 * A TanStack Query `retry` policy for v3 reads: a 4xx is the server's answer, and asking again only
 * delays it — a dashboard the caller may not open spun for seconds through three retries before its
 * error showed, and every retry spent the caller's rate limit. Network failures and 5xx are retried up
 * to `maxRetries` times. The one 4xx retried is a 429 asking for a short wait (`Retry-After` of a few
 * seconds), so a large dashboard waits for a free chart query slot instead of showing errors.
 */
export const retryUnlessClientError =
  (maxRetries: number) =>
  (failureCount: number, error: unknown): boolean => {
    if (isBriefBusy(error)) return failureCount < MAX_BUSY_RETRIES;
    return (
      failureCount < maxRetries && !(error instanceof V3ApiError && error.status >= 400 && error.status < 500)
    );
  };

/**
 * The `retryDelay` that goes with `retryUnlessClientError`: a 429's own `Retry-After`, with a little
 * jitter so a dashboard's widgets do not all come back at once; otherwise TanStack's default backoff.
 */
export const v3RetryDelay = (failureCount: number, error: unknown): number =>
  isBriefBusy(error)
    ? (error.retryAfter as number) * 1000 + Math.floor(Math.random() * 500)
    : Math.min(1000 * 2 ** failureCount, 30_000);

export function getV3ApiErrorMessage(error: unknown, fallbackMessage: string): string {
  if (error instanceof V3ApiError) {
    return error.detail;
  }

  if (error instanceof Error && error.message) {
    return error.message;
  }

  return fallbackMessage;
}

export async function parseV3ApiError(response: Response): Promise<V3ApiError> {
  let problemBody: TV3ProblemBody | undefined;

  try {
    problemBody = (await response.json()) as TV3ProblemBody;
  } catch {
    problemBody = undefined;
  }

  return new V3ApiError({
    status: problemBody?.status ?? response.status,
    detail: problemBody?.detail ?? response.statusText ?? "An unexpected error occurred.",
    code: problemBody?.code,
    requestId: problemBody?.requestId ?? response.headers.get("X-Request-Id") ?? undefined,
    invalid_params: problemBody?.invalid_params,
    details: problemBody?.details,
    retryAfter: parseRetryAfterSeconds(response.headers.get("Retry-After")),
  });
}

/** `Retry-After` in its delay-seconds form; the HTTP-date form is not one v3 sends. */
const parseRetryAfterSeconds = (value: string | null): number | undefined => {
  if (value === null || !/^\d+$/.test(value.trim())) return undefined;
  return Number(value.trim());
};

