import "server-only";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { problemForbidden, problemInternalError, problemUnprocessableContent, successResponse } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromApiKeyId } from "@/lib/utils/helper";
import { capturePostHogEvent } from "@/lib/posthog";
import { rotateApiKey } from "@/modules/organization/settings/api-keys/lib/api-key";

/**
 * Rotate an API key: replace its secret while keeping label and organizationAccess intact.
 * Session-only — mirrors the authorization of the old `rotateApiKeyAction`.
 */
export async function rotateV3ApiKey(
  params: {
    authentication: TV3Authentication;
    apiKeyId: string;
    auditLog?: TV3AuditLog;
    requestId: string;
    instance?: string;
  }
): Promise<Response> {
  const { authentication, apiKeyId, auditLog, requestId, instance } = params;

  // Resolve the organization from the key itself (never trust a client-supplied workspace).
  const organizationId = await getOrganizationIdFromApiKeyId(apiKeyId);
  if (!organizationId) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  // Authorize: the user must have apiKey.manage on this key.
  const actor = authentication && "user" in authentication && authentication.user?.id
    ? { type: "user" as const, id: authentication.user.id }
    : null;
  if (!actor) {
    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
  }

  await assertCan(actor, "apiKey.manage", { type: "apiKey", id: apiKeyId });

  // Resolve workspace context for audit logging.
  const access = await requireV3WorkspaceAccess(
    authentication,
    organizationId,
    "readWrite" as "readWrite",
    requestId,
    instance
  );
  if (access instanceof Response) return access;

  if (auditLog) {
    auditLog.organizationId = organizationId;
    auditLog.targetId = apiKeyId;
  }

  const result = await rotateApiKey(apiKeyId, actor.id);

  if (auditLog) {
    auditLog.newObject = { id: result.id, label: result.label };
  }

  capturePostHogEvent(
    actor.id,
    "api_key_rotated",
    { api_key_id: result.id },
    { organizationId }
  );

  // Return the new key in the v2 format (actualKey is the plaintext secret with fbk_ prefix).
  return successResponse(
    {
      id: result.id,
      label: result.label,
      actualKey: result.actualKey,
      createdAt: result.createdAt,
      apiKeyWorkspaces: result.apiKeyWorkspaces,
    },
    { requestId }
  );
}

/**
 * POST /api/v3/api-keys/{apiKeyId}/rotate — rotate an API key's secret.
 * Thin adapter delegating to @formbricks/organization/settings/api-keys/lib/api-key#rotateApiKey.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { rotateV3ApiKey } from "../lib/operations";
import { ZV3ApiKeyIdParams } from "../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "updated",
  targetType: "apiKey",
  schemas: { params: ZV3ApiKeyIdParams },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    rotateV3ApiKey({
      authentication,
      apiKeyId: parsedInput.params.apiKeyId,
      auditLog,
      requestId,
      instance,
    }),
});

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/** Rotate an API key's secret; the caller receives the new plaintext key once. */
export async function rotateApiKeyClient({
  apiKeyId,
}: {
  apiKeyId: string;
}): Promise<{
  id: string;
  label: string;
  actualKey: string;
  createdAt: Date;
  apiKeyWorkspaces: Array<{ workspaceId: string; permission: string }>;
}> {
  const response = await fetch(`/api/v3/api-keys/${encodeURIComponent(apiKeyId)}/rotate`, {
    method: "POST",
    cache: "no-store",
    signal: AbortSignal.timeout(15_000),
  });
  if (!response.ok) throw await parseV3ApiError(response);
  const body = await response.json();
  return body.data;
}

